#!/usr/bin/env node

"use strict";

const fs = require("fs");
const parseArgs = require("minimist");
const Jibo = require("@jibo/jibo-server-client");
const syslog = require("modern-syslog");
const identity_file = "/var/jibo/identity.json";
const url = require('url');

let args = process.argv.slice(2);
let argv = parseArgs(args);

function usage() {
    console.log("Usage:", process.argv[1], "[options]");
    console.log("");
    console.log("OPTIONS:");
    console.log("  -h,--help            print this message");
    console.log("  --credentials FILE   path to credentials.json");
    console.log("  --file FILE          logfile to gzip and upload.");
    console.log("  --gzip FILE          gzip logfile to upload");
    console.log("  --kind KIND          specify the kind of log, default: LOG");
}

if (argv.h || argv.help) {
    usage();
    process.exit(0);
}

if (!argv.credentials) {
    console.log("ERROR: credentials file not specified!");
    usage();
    process.exit(1);
}

if (!argv.file && !argv.gzip) {
    console.log("ERROR: file not specified!");
    usage();
    process.exit(1);
}

function get_identity() {
    try {
        let id = JSON.parse(fs.readFileSync(identity_file));
        return id;
    } catch (error) {
        syslog.error("Failed to read identity:", error);
        process.exit(1);
    }
}

if (!fs.existsSync(argv.credentials)) {
    syslog.warn("ERROR: No credentials!");
    process.exit(1);
}

Jibo.config.loadFromPath(argv.credentials);

//TODO: uncomment on the robot
let identity = get_identity();

syslog.init("jibo-log-client-async", syslog.LOG_PID | syslog.LOG_ODELAY, syslog.LOG_LOCAL0);
let fileName = argv.file ? argv.file : argv.gzip;
const logsize = fs.statSync(fileName).size;
syslog.info("Upload log", fileName, " size", logsize, "bytes");


let kind = "LOG";
if (argv.kind){
    kind = argv.kind;
}

new Jibo.Log().putEventsAsync({ kind: kind, serial: identity.serial_number }, function (err, result) {
  if (err) {
    return console.error(err);
  }
  const https = require('https');

  const uploadUrl = url.parse(result.uploadUrl);
  const options = {
    method: 'PUT',
    host: uploadUrl.host,
    path: uploadUrl.path,
    headers: {
      Accept: '*/*',
      'Content-Type': 'application/octet-stream',
      'Content-Length': logsize //Content-Length is required to upload to AWS S3 pre-signed URL
    }
  }
  let readStream = fs.createReadStream(fileName);
  if (argv.file){//if plaintext file - GZIP it
    const zlib = require('zlib');
    let buffer = '';
    readStream.on('data', chunk=>{
      buffer+=chunk.toString();
    });
    readStream.on('end', ()=>{
      zlib.gzip(buffer, (_, result) => {
        options.headers['Content-Length'] = result.length;

        let request = https.request(options, res=>uploadCb(res));
        request.on('error', e => console.error(`problem with request: ${e.message}`));
        request.end(result);
      });
    });
  }else{
    let request = https.request(options, res=>uploadCb(res));
    request.on('error', e => console.error(`problem with request: ${e.message}`));
    readStream.on('data', chunk=>request.write(chunk));
    readStream.on('end', ()=>request.end());
  }
});

function uploadCb(res){
    let responseBody = '';
    res.on('data', (chunk) => {
      responseBody+=chunk;
    });
    res.on('end', () => {
      if (res.statusCode >= 300){
        console.log(`STATUS: ${res.statusCode}, HEADERS: ${JSON.stringify(res.headers)}, BODY:${responseBody}`);
      }
    });
}
